/**
 * Fork gate: fails if the previous brand still leaks anywhere.
 *
 *   npm run fork:check                scans for "shindara" (this template's brand)
 *   npm run fork:check -- --from=Ada   scans for "ada" instead
 *   node scripts/fork-check.mjs --root=/tmp/fork --from=Shindara
 *
 * Workflow: fork → edit site.config.ts + catalog + .env → run the gate.
 * Exit 0 = clean delivery. Exit 1 = file:line hits to fix first.
 * index.html is allowlisted (generated by sync-brand.mjs from the config).
 */
import { execSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const args = process.argv.slice(2);
const rootArg = args.find((a) => a.startsWith("--root="));
const fromArg = args.find((a) => a.startsWith("--from="));
const root = rootArg ? rootArg.slice("--root=".length) : process.cwd();
const needle = (fromArg ? fromArg.slice("--from=".length) : "shindara").toLowerCase();

const ALLOWLIST = new Set(["scripts/fork-check.mjs", "index.html"]);

function trackedFiles() {
  try {
    const out = execSync("git ls-files", { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
    return out.split("\n").map((s) => s.trim()).filter(Boolean);
  } catch {
    // Not a git checkout (or git missing): walk, skipping runtime/build dirs.
    const skip = new Set(["node_modules", "dist", "data", "uploads", ".git"]);
    const found = [];
    const walk = (dir) => {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        if (skip.has(entry.name)) continue;
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full);
        else if (entry.isFile()) found.push(path.relative(root, full));
      }
    };
    walk(root);
    return found;
  }
}

const hits = [];
for (const rel of trackedFiles()) {
  if (ALLOWLIST.has(rel.replace(/\\/g, "/"))) continue;
  const full = path.join(root, rel);
  let text;
  try {
    text = fs.readFileSync(full, "utf8");
  } catch {
    continue; // binary (images, lockfiles with odd bytes) — skip
  }
  if (text.toLowerCase().includes("\ufffd")) continue; // binary heuristic
  text.split("\n").forEach((line, i) => {
    if (line.toLowerCase().includes(needle)) {
      hits.push(`${rel}:${i + 1}: ${line.trim().slice(0, 120)}`);
    }
  });
}

if (hits.length) {
  console.error(`fork:check FAILED — "${needle}" still appears in ${hits.length} place(s):`);
  for (const h of hits.slice(0, 50)) console.error(`  ${h}`);
  if (hits.length > 50) console.error(`  …and ${hits.length - 50} more`);
  console.error('\nFix: move brand content into src/site.config.ts, then re-run.');
  process.exit(1);
}
console.log(`fork:check passed — no "${needle}" outside generated files.`);
